    { channel: "Osmosis", title: "Batch and Continuous Culture - Methods and Applications", note: "The batch culture and the continuous culture, the preservation of the cultures, and the applications in the industry.", url: "https://www.youtube.com/results?search_query=batch+continuous+culture+preservation+applications" },
    { channel: "Armando Hasudungan", title: "Control of Microbial Growth - Physical and Chemical Methods", note: "The physical and the chemical methods for the control of the bacterial growth, including the heat, the radiation, the filtration and the disinfectants.", url: "https://www.youtube.com/results?search_query=control+microbial+growth+physical+chemical+methods" }
